import { createId } from './ids.mjs';
import { parseRecoveryFile } from './recovery.mjs';
import { buildPlan, summarizeMeals, weightTrend, catalog } from './domain.mjs';
const paths={journal:'M12 5c-3-2-6-2-9-1v15c3-1 6-1 9 1 3-2 6-2 9-1V4c-3-1-6-1-9 1Zm0 0v15M6 8h3m-3 4h3m6-4h3m-3 4h3',help:'M12 3a9 9 0 0 0-8 13l-1 5 5-1a9 9 0 1 0 4-17ZM9 9a3 3 0 0 1 6 0c0 2-3 2-3 4m0 3v.2',bell:'M5 17h14l-2-3V9a5 5 0 0 0-10 0v5l-2 3Zm5 3h4M12 2v2',search:'M10 3a7 7 0 1 0 0 14 7 7 0 0 0 0-14Zm5 12 6 6',grid:'M3 3h7v7H3ZM14 3h7v7h-7ZM3 14h7v7H3ZM14 14h7v7h-7Z',person:'M12 4a4 4 0 1 0 0 8 4 4 0 0 0 0-8ZM4 21v-2a8 8 0 0 1 16 0v2',scan:'M8 3H4a1 1 0 0 0-1 1v4m13-5h4a1 1 0 0 1 1 1v4M3 16v4a1 1 0 0 0 1 1h4m8 0h4a1 1 0 0 0 1-1v-4M6 9h12v6H6ZM2 12h20',flame:'M12 3c1 4-3 5-3 8 0 1 .7 2 2 2 2 0 3-2 2-4 4 3 6 5 6 8a7 7 0 0 1-14 0c0-4 3-5 7-14Z',home:'M3 10 12 3l9 7v10a1 1 0 0 1-1 1h-5v-7H9v7H4a1 1 0 0 1-1-1Z',food:'M4 3v7m3-7v7m3-7v7M4 7h6m-3 3v11M18 3c-3 3-3 7 0 8h2V3h-2Zm1 8v10',calendar:'M5 5h14a2 2 0 0 1 2 2v12a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2V7a2 2 0 0 1 2-2ZM7 3v4m10-4v4M3 11h18m-14 4h2m4 0h2',activity:'M3 12h4l3-8 4 16 3-8h4',chart:'M4 3v17h17M7 14l4-4 4 2 5-7',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8ZM9 3l-1 3-3 1-2 3 2 2-1 3 2 3 3-1 2 3h3l1-3 3-1 2-3-2-2 1-3-2-3-3 1-2-3Z',plus:'M12 5v14M5 12h14',minus:'M5 12h14',arrow:'M5 12h14m-5-5 5 5-5 5',chevron:'m9 5 7 7-7 7',check:'m5 12 4 4L19 6',close:'m6 6 12 12M6 18 18 6',water:'M12 3c-2 4-7 8-7 12a7 7 0 0 0 14 0c0-4-5-8-7-12Z',moon:'M20 14a8 8 0 0 1-10-10 8 8 0 1 0 10 10Z',sun:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8ZM12 2v2m0 16v2M2 12h2m16 0h2M5 5l2 2m10 10 2 2M5 19l2-2M17 7l2-2',info:'M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18ZM12 11v6m0-10v1',camera:'M8 5h8l2 3h3v12H3V8h3ZM12 10a4 4 0 1 0 0 8 4 4 0 0 0 0-8Z',run:'M14 3a1.5 1.5 0 1 0 0 3 1.5 1.5 0 0 0 0-3ZM4 10l4-2 5 2 3 4h5M13 10l-3 5 5 2 2 5M10 15l-3 5H3',bar:'M3 5h18M5 3v4m14-4v4M10 8a2 2 0 1 0 4 0M7 5v7l5 3 5-3V5M12 15v6',racket:'M16 3c-3-1-8 2-8 6s4 5 7 3 6-8 1-9ZM9 12l-6 9m3-4 2 2',walk:'M13 3a1.5 1.5 0 1 0 0 3 1.5 1.5 0 0 0 0-3ZM6 11l5-3 4 4 4 1M11 8l-1 7-4 6M10 15l5 2 1 5',refresh:'M20 8a8 8 0 0 0-14-3L3 8m0-5v5h5M4 16a8 8 0 0 0 14 3l3-3m0 5v-5h-5',trash:'M3 6h18M9 6V3h6v3M5 6l1 15h12l1-15M10 10v7m4-7v7',download:'M12 3v12m-5-5 5 5 5-5M4 17v4h16v-4',leaf:'M20 3C8 3 2 9 5 16s15 5 15-13ZM5 20 16 9',clock:'M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18ZM12 7v5l3 2',bolt:'m13 2-9 12h7l-1 8 10-13h-7Z',scale:'M5 4h14a2 2 0 0 1 2 2v14H3V6a2 2 0 0 1 2-2ZM8 8a5 5 0 0 1 8 0l-4 4Z',lock:'M6 10h12v11H6ZM8 10V6a4 4 0 0 1 8 0v4'};
const ic=(n)=>`<svg class="icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[n]||paths.activity}"/></svg>`;
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const dayKey=(date=new Date())=>new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Kuala_Lumpur',year:'numeric',month:'2-digit',day:'2-digit'}).format(date);
const offset=(date,days)=>{const d=new Date(`${date}T12:00:00+08:00`);d.setUTCDate(d.getUTCDate()+days);return dayKey(d)};
const backend=new ServerJournal();let hydrating=false;let activePhotoDraft=null;let draftNotice='';let useAI=false;let latestReview=null;let dailyRecap=null;let recapLoaded=false;let recapError=false;let recapGeneration=0;
const today=dayKey();let selected=today;let page='today';let foodTab='manual';let draft=[];let draftPhoto=null;let editMeal=null;let viewWeeks=7;
const id=createId;const fmt=n=>Math.round(n).toLocaleString();const pretty=(date,opts={month:'short',day:'numeric'})=>new Intl.DateTimeFormat('en-MY',{timeZone:'Asia/Kuala_Lumpur',...opts}).format(new Date(date+'T12:00:00+08:00'));

const presets=[{id:'chicken-bowl',name:'Chicken & rice bowl',emoji:'🍚',items:[{food:'rice',amount:200},{food:'chicken',amount:150},{food:'greens',amount:150},{food:'egg',amount:1}]},{id:'snack',name:'Eggs & apple',emoji:'🥚',items:[{food:'egg',amount:2},{food:'apple',amount:1}]}];
function foodItem(food,amount){const c=catalog.find(f=>f.id===food);return {id:id(),food,name:c.name,amount,unit:c.unit,kcal:c.kcal*amount/c.basis,protein:+(c.protein*amount/c.basis).toFixed(1),quality:'saved_serving',low:Math.round(c.kcal*amount/c.basis*.9),high:Math.round(c.kcal*amount/c.basis*1.1),emoji:c.emoji};}
function seed(demo=true){const settings={name:'Alex',startWeight:75.9,targetWeight:66,endDate:offset(today,87),calorieFloor:1500,proteinTarget:120,waterTarget:2.5,availableMinutes:30,mealTimes:{Lunch:'12:30',Snack:'15:30',Dinner:'19:30'},fasting:false,eatFrom:'12:00',eatUntil:'20:00'};const activities=[{id:'jog',name:'Jogging',icon:'run',type:'cardio',metric:'distance',preference:'most',enabled:true,partner:false,available:true},{id:'bar',name:'Pull-up bar',icon:'bar',type:'strength',metric:'reps',preference:'mid',enabled:true,partner:false,available:true},{id:'badminton',name:'Badminton',icon:'racket',type:'sport',metric:'duration',preference:'least',enabled:true,partner:true,available:false},{id:'walk',name:'Walking',icon:'walk',type:'cardio',metric:'duration',preference:'mid',enabled:true,partner:false,available:true}];return {version:1,demo,revision:0,settings,activities,meals:demo?[{id:id(),date:today,slot:'Lunch',items:[foodItem('rice',200),foodItem('chicken',150),foodItem('egg',1),foodItem('greens',100)]},{id:id(),date:today,slot:'Snack',items:[foodItem('egg',2),foodItem('apple',1)]}]:[],sessions:demo?[{id:id(),date:offset(today,-1),activityId:'jog',name:'Jogging',duration:25,distance:2.5,effort:5,status:'completed'},{id:id(),date:offset(today,-3),activityId:'bar',name:'Pull-up bar',duration:15,reps:12,sets:3,effort:5,status:'completed'}]:[],weights:demo?[75.9,75.8,75.85,75.7,75.75,75.6].map((kg,i)=>({date:offset(today,i-5),kg})):[],days:demo?{[today]:{energy:3,water:1.5,sleep:7,soreness:'none'}}:{},plan:null,savedPresets:[]};}
let state;try{state=JSON.parse(localStorage.getItem('burnrate-v1'));if(!validBackup(state))state=seed()}catch{state=seed()}
function persist(){try{localStorage.setItem('burnrate-v1',JSON.stringify(state))}catch{toast('Storage is full. Export your data before continuing.')}if(backend.connected&&!hydrating){const revision=state.revision;backend.queue(state).then(async r=>{if(state.revision===revision){state={...r.state,plan:state.plan};hydrating=true;persist();hydrating=false;await refreshServerPlan(false);}}).catch(e=>toast('Local backup saved. '+e.message));}}
async function refreshServerPlan(ai=false){if(!backend.connected)return;try{const p=await backend.plan(today,ai);if(p.revision===state.revision){state.plan=p;hydrating=true;persist();hydrating=false;render();}}catch(e){toast('Local plan available. '+e.message);}}
function currentPlan(){return state.plan&&state.plan.revision===state.revision&&state.plan.date===offset(today,1)?state.plan:buildPlan(state,today);}

async function refreshDailyRecap(){
  if(!backend.connected)return;const generation=recapGeneration;
  try{const result=await backend.request('daily-recap');if(generation!==recapGeneration)return;const changed=!recapLoaded||recapError||JSON.stringify(dailyRecap)!==JSON.stringify(result.recap);dailyRecap=result.recap;recapLoaded=true;recapError=false;if(changed&&page==='journal')render();}
  catch{if(generation!==recapGeneration)return;recapError=true;if(page==='journal')render();}
}
function dailyRecapCard(){
  const r=dailyRecap;
  const head='<div class="card-head"><h2>Your midnight recap</h2><span class="badge outline">12:00 AM · MYT</span></div>';
  if(!r)return `<section class="card midnight-recap">${head}<p class="muted small">${!backend.connected?'Connect to your Python server for automatic midnight recaps.':recapError?'Unable to load your recap. Try reopening the journal.':!recapLoaded?'Loading your saved recap…':'Your first recap appears after midnight. It will summarize the day just ended and suggest the next day’s focus.'}</p></section>`;
  const n=r.next_plan;
  return `<section class="card midnight-recap">${head}<p class="muted small">${pretty(r.day,{weekday:'short',day:'numeric',month:'short'})} · saved ${new Date(r.generated_at).toLocaleTimeString('en-MY',{timeZone:'Asia/Kuala_Lumpur',hour:'2-digit',minute:'2-digit'})}${r.delayed?' · delayed after server restart':''}</p><div class="recap-metrics"><div><span>Food logged${r.food.complete?'':' · partial day'}</span><strong>${r.food.kcal_used===null?'Not logged':fmt(r.food.kcal_used)+' kcal'}</strong></div><div><span>Movement</span><strong>${fmt(r.movement_minutes)} min${r.steps===null?'':' · '+fmt(r.steps)+' steps'}</strong></div><div><span>Water</span><strong>${r.water_l===null?'Not logged':r.water_l+' L'}</strong></div><div><span>Sleep / energy</span><strong>${r.sleep_hours===null?'—':r.sleep_hours+' h'} / ${r.energy===null?'—':r.energy+' of 5'}</strong></div></div><p class="muted small">${r.activities.length?r.activities.map(a=>esc(a.name)+' · '+fmt(a.duration)+' min · '+esc(a.status)).join('; '):'No movement sessions logged for this date.'}</p><div class="recap-next"><h3>Next-day focus · ${pretty(n.date)}</h3><p>${esc(n.valid?(n.activity?n.activity.name+' · '+n.activity.detail:'Recovery day · rest from training'):n.error)}</p><ul>${r.focus.map(f=>`<li>${esc(f)}</li>`).join('')}</ul><p class="muted small">Goal: ${r.goal.target_kg} kg by ${pretty(r.goal.date)}. ${r.goal.latest_kg===null?'No weight logged yet.':'Latest logged weight: '+r.goal.latest_kg+' kg ('+pretty(r.goal.latest_weight_date)+').'} This plan supports your routine; it does not guarantee the goal date.</p></div><p class="footer-note">Saved once after midnight. Later edits do not rewrite this recap. ${r.delayed?'Based on logs available when the server restarted.':''}</p></section>`;
}
setInterval(()=>{if(page==='journal')refreshDailyRecap();},60000);
document.addEventListener('visibilitychange',()=>{if(!document.hidden&&page==='journal')refreshDailyRecap();});

function change(){state.revision++;persist();render()}
function getDay(){return state.days[selected]||{energy:null,water:0,sleep:null,soreness:'none'}}
function meals(date=selected){return state.meals.filter(m=>m.date===date)}
function totals(date=selected){return summarizeMeals(meals(date))}
function dayUpdate(k,v){state.days[selected]={...getDay(),[k]:v};change()}
function toast(s){const el=document.querySelector('#toast');el.textContent=s;el.classList.add('show');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>el.classList.remove('show'),3000)}
function nav(p){if(p==='today')selected=today;page=p;render();if(p==='journal')refreshDailyRecap();window.scrollTo({top:0,behavior:'smooth'})}
const navItems=[['today','home','Today'],['food','food','Food'],['plan','calendar','My plan'],['activity','activity','Activity'],['progress','chart','Progress']];
function navHTML(cls){return `<nav class="${cls}" aria-label="${cls==='bottom-nav'?'Mobile navigation':'Main navigation'}">${navItems.map(([p,i,label])=>`<button class="${cls==='nav-list'?'nav-btn ':''}${page===p?'active':''}" data-nav="${p}" ${page===p?'aria-current="page"':''}>${ic(i)}<span>${label}</span></button>`).join('')}${cls==='nav-list'?`<button class="nav-btn ${page==='settings'?'active':''}" data-nav="settings">${ic('settings')}<span>Settings</span></button>`:''}</nav>`}
function render(){const labels={today:'Daily overview',food:'Food journal',plan:'Your rolling plan',activity:'Movement library',progress:'Your progress',settings:'Your preferences',journal:'Daily overview'};document.querySelector('#app').innerHTML=`<div class="layout ${page==='today'?'home-layout':''}"><aside class="sidebar"><div class="brand"><span class="brand-mark">${ic('flame')}</span><div>BurnRate<small>YOUR DAILY RHYTHM</small></div></div>${navHTML('nav-list')}<div class="sidebar-bottom"><div class="goal-mini"><span class="eyebrow">One day at a time</span><h3>Small steps. Real change.</h3><p>Your plan moves with you, every day.</p><button class="text-btn" data-nav="plan">See your plan ${ic('arrow')}</button></div><div class="profile"><div class="avatar">${esc(state.settings.name.slice(0,1).toUpperCase())}</div><div><strong class="small">${esc(state.settings.name)}</strong><p class="small muted">Your personal space</p></div></div></div></aside><main class="main"><header class="topbar reference-topbar"><button class="utility-button" data-action="help" aria-label="How to use BurnRate">${ic('help')}</button><div class="reference-wordmark">BurnRate <span>${state.demo?'Sample data':'Your journal'}</span></div><div class="header-controls"><button class="utility-button notification-button" data-action="updates" aria-label="View today’s updates">${ic('bell')}${Object.keys(state.settings.mealTimes).filter(slot=>!meals(today).some(m=>m.slot===slot)).length?`<span class="notification-count">${Object.keys(state.settings.mealTimes).filter(slot=>!meals(today).some(m=>m.slot===slot)).length}</span>`:''}</button><button class="utility-button" data-nav="settings" aria-label="User settings">${ic('settings')}</button></div></header><div id="view">${({today:todayView,journal:journalView,food:foodView,plan:planView,activity:activityView,progress:progressView,settings:settingsView})[page]()}</div><p class="intro-note">${ic('lock')} ${backend.connected?'Saved to server · browser backup':'Saved on this browser'} · ${state.demo?'Exploring with sample data':'Your private local journal'}</p></main><div class="floating-controls"><nav class="floating-dock" aria-label="Quick navigation"><button data-nav="today" class="${page==='today'?'active':''}" aria-label="Home" ${page==='today'?'aria-current="page"':''}>${ic('grid')}</button><button data-nav="journal" class="${page==='journal'?'active':''}" aria-label="View journal" ${page==='journal'?'aria-current="page"':''}>${ic('journal')}</button></nav><button class="floating-add" data-action="quick-add" aria-label="Add a journal entry">${ic('plus')}</button></div></div>`;bindView();}
function heading(title,sub,action=''){return `<div class="heading"><div><h1>${title}</h1><p class="muted">${sub}</p></div>${action||`<div class="date-pill">${ic('calendar')}${pretty(selected,{weekday:'short',day:'numeric',month:'short'})}</div>`}</div>`}
function weekStrip(){const dow=new Date(selected+'T12:00:00+08:00').getUTCDay();const start=offset(selected,-((dow+6)%7));return `<div class="journal-date-row"><span class="eyebrow">Your journal</span><label class="date-control">${ic('calendar')}<input type="date" id="journal-date" aria-label="Journal date" value="${selected}" max="${today}"></label></div><div class="week-strip" aria-label="Select journal date">${Array.from({length:7},(_,i)=>{const d=offset(start,i);return `<button class="day-btn ${d===selected?'active':''}" data-date="${d}" aria-label="${pretty(d,{weekday:'long',month:'long',day:'numeric'})}" ${d>today?'disabled':''}><span>${pretty(d,{weekday:'short'})}</span><strong>${pretty(d,{day:'numeric'})}</strong><span class="day-dot" style="opacity:${state.meals.some(m=>m.date===d)||state.sessions.some(s=>s.date===d)?1:.2}"></span></button>`}).join('')}</div>`}
function mealRow(m,actions=false){const t=summarizeMeals([m]);return `<div class="meal-row"><div class="meal-art">${m.items[0]?.emoji||'🍽️'}</div><div class="meal-info"><h3>${esc(m.slot)} <span class="badge ${t.estimated?'warm':''}" style="margin-left:5px">${t.estimated?'Estimated':'Confirmed'}</span></h3><p>${m.items.map(i=>esc(i.name.split(' · ')[0])).join(' · ')}</p></div><div class="meal-kcal">${fmt(t.kcal)}<small>kcal · ${fmt(t.protein)} g protein</small></div>${actions?`<div class="meal-actions"><button class="text-btn" data-edit-meal="${esc(m.id)}" aria-label="Edit ${esc(m.slot)}">Edit ${ic('chevron')}</button><button class="text-btn" data-delete-meal="${esc(m.id)}" aria-label="Delete ${esc(m.slot)}">${ic('trash')} Delete</button></div>`:''}</div>`}
function todayView(){const t=totals(today),d=state.days[today]||{},pending=Object.keys(state.settings.mealTimes).filter(slot=>!meals(today).some(m=>m.slot===slot));return `<section class="home-intro"><h1><span>Hi ${esc(state.settings.name)},</span><br>Here’s your day.</h1></section><section class="day-glance"><div class="glance-header"><h2>Your day, so far.</h2></div><div class="glance-stats"><div><span>Food logged</span><strong>${meals(today).length?fmt(t.kcal):'—'}<small> kcal</small></strong></div><div><span>Energy</span><button data-action="recovery">${d.energy?`${d.energy}<small> / 5</small>`:'Check in'}</button></div><div class="glance-water"><button class="water-shortcut" data-action="water-today" aria-label="Log water for today"><span>Water</span><strong>${(d.water||0).toFixed(2).replace(/0$/,'')}<small> L</small> ${ic('plus')}</strong></button></div></div><p>${pending.length?`${esc(pending.join(' & '))} still unlogged. Your total is a partial day.`:'All meal slots logged. Your estimates stay visible.'}</p></section><div class="action-grid"><button class="action-tile" data-action="photo"><span class="tile-icon">${ic('scan')}</span><strong>Log food</strong><span>Photo, portions, usual meals…</span></button><button class="action-tile" data-nav="activity"><span class="tile-icon">${ic('run')}</span><strong>Move</strong><span>Jog, pull-ups, badminton…</span></button><button class="action-tile" data-nav="plan"><span class="tile-icon">${ic('calendar')}</span><strong>My plan</strong><span>A rhythm for tomorrow…</span></button><button class="action-tile" data-nav="progress"><span class="tile-icon">${ic('chart')}</span><strong>Progress</strong><span>Your weight, your patterns…</span></button></div><div class="home-search-wrap"><label class="home-search">${ic('search')}<input id="home-search" type="search" placeholder="Search" aria-label="Search meals, activities and pages" autocomplete="off"><span class="search-shortcut">${ic('food')}</span></label><div id="search-results" class="search-results" aria-live="polite" hidden></div></div>`}
async function weeklyReviewSheet(){openSheet('Your weekly reflection.','Reviewing the last seven days of confirmed data…','<p class="muted">Preparing your summary.</p>');try{latestReview=await backend.review(today,useAI);openSheet('Your weekly reflection.',latestReview.source==='ai'?'AI review from calculated summaries':'Server summary from confirmed logs',`<div class="help-steps">${latestReview.findings.map(f=>`<div>${ic('chart')}<p class="muted small">${esc(f)}</p></div>`).join('')}</div><p class="muted small">${esc(latestReview.reason)}</p><div class="notice green">${latestReview.suggestions.map(esc).join(' · ')}</div>${latestReview.proposed_end_date?`<div class="notice">Suggested goal date: ${esc(latestReview.proposed_end_date)}. Your current goal is unchanged; review it in Settings.</div>`:''}`)}catch(error){openSheet('Your weekly reflection.','Your local reflection remains available.',`<div class="notice">${esc(error.message)}</div>`)}}
function helpSheet(){openSheet('Your day. Your way.','Start with one small entry. BurnRate keeps your routine in view.',`<div class="help-steps"><div>${ic('scan')}<span><strong>Log a meal</strong><p>Use a usual meal or enter food details. Review portions, then confirm.</p></span></div><div>${ic('run')}<span><strong>Record your movement</strong><p>Add activities, choose your favorites, and log what you actually did.</p></span></div><div>${ic('calendar')}<span><strong>Look ahead</strong><p>Tomorrow’s template plan responds to your recovery and availability.</p></span></div></div><button class="btn full" id="help-done">Got it</button>`);document.querySelector('#help-done').onclick=()=>sheet.close()}
function quickAdd(){openSheet('A small step today.','What would you like to add?',`<div class="quick-add-list">${[['photo','scan','Food photo','Attach a photo and enter meal details'],['food','food','Meal entry','A usual meal or manual portion'],['water','water','Water','A glass, bottle or custom amount'],['log-session','run','Activity','Record a completed or partial session'],['weight','scale','Weight','Add one measurement'],['recovery','moon','Check-in','Sleep, energy and recovery']].map(([a,i,title,sub])=>`<button data-quick="${a}">${ic(i)}<span><strong>${title}</strong><small>${sub}</small></span>${ic('chevron')}</button>`).join('')}</div>`);document.querySelectorAll('[data-quick]').forEach(b=>b.onclick=()=>action(b.dataset.quick))}
function updatesSheet(){const pending=Object.keys(state.settings.mealTimes).filter(slot=>!meals(today).some(m=>m.slot===slot));openSheet('A little check-in.','Here’s what’s open in your journal today.',`<div class="notice">${pending.length?`${esc(pending.join(', '))} ${pending.length===1?'is':'are'} not logged yet. Your calorie total is incomplete.`:'All your meal slots have entries today.'}</div><p class="muted small" style="margin:20px 0">Your next plan uses your latest confirmed meals, activity and recovery. Goal dates only change when you edit them.</p><button class="btn full" id="updates-journal">Open food journal ${ic('arrow')}</button>`);document.querySelector('#updates-journal').onclick=()=>{sheet.close();nav('food')}}
function bindSearch(){const input=document.querySelector('#home-search');if(!input)return;input.oninput=()=>{const q=input.value.trim().toLowerCase(),box=document.querySelector('#search-results');if(!q){box.hidden=true;box.innerHTML='';return}const options=[...navItems.map(([target,icon,name])=>({target,icon,name,kind:'page'})),{target:'journal',icon:'home',name:'Daily journal',kind:'page'},{target:'settings',icon:'settings',name:'Settings',kind:'page'},...allPresets().map(p=>({target:p.id,icon:'food',name:p.name,kind:'meal'})),...state.activities.map(a=>({target:a.id,icon:a.icon,name:a.name,kind:'activity'}))].filter(x=>x.name.toLowerCase().includes(q));box.hidden=false;box.innerHTML=options.length?options.slice(0,8).map((r,i)=>`<button data-result="${i}">${ic(r.icon)}<span>${esc(r.name)}<small>${r.kind==='meal'?'Saved meal':r.kind==='activity'?'Log a session':'Open page'}</small></span>${ic('chevron')}</button>`).join(''):'<p>No matches. Try “food”, “jogging”, or “plan”.</p>';box.querySelectorAll('[data-result]').forEach(b=>b.onclick=()=>{const r=options[Number(b.dataset.result)];if(r.kind==='meal')loadPreset(r.target);else if(r.kind==='activity')sessionSheet(r.target);else nav(r.target)})};}
function journalView(){const t=totals(),d=getDay(),s=state.settings;const logged=meals().length;const pending=Object.keys(s.mealTimes).filter(slot=>!meals().some(m=>m.slot===slot));const latest=state.weights.filter(w=>w.date<=selected).at(-1);const circ=2*Math.PI*71;const completed=state.sessions.filter(x=>x.date===selected);const planned=currentPlan();return `${heading(selected===today?`A little better, every day.`:`Your day, at a glance.`,selected===today?`Hello ${esc(s.name)}. Let's find your rhythm today.`:`A look back at ${pretty(selected,{weekday:'long',day:'numeric',month:'short'})}.`)}${weekStrip()}${dailyRecapCard()}<section class="card plan-card journal-plan-top"><div class="card-head"><span class="eyebrow">Tomorrow, thoughtfully</span><span class="badge">${ic('leaf')} Template plan</span></div><h2>${planned.rest?'A little room to recover.':'A plan that moves with you.'}</h2><p>${esc(planned.reason)}</p><div class="plan-detail">${ic(planned.activity?.icon||'moon')}<div><strong>${esc(planned.activity?.name||'Recovery day')}</strong><small>${esc(planned.activity?.detail||'Rest · no planned training')}</small></div></div><button class="btn" data-nav="plan">Explore tomorrow ${ic('arrow')}</button></section><div class="dashboard-grid"><div class="stack"><section class="card nourishment-card"><div class="card-head"><h2>${selected===today?"Today's nourishment":"Nourishment"}</h2><span class="badge ${pending.length?'warm':''}">${logged} meals logged</span></div><div class="nutrition"><div class="ring-wrap"><svg class="ring" viewBox="0 0 174 174" aria-hidden="true"><circle cx="87" cy="87" r="71" stroke="#eceeed"/><circle cx="87" cy="87" r="71" stroke="#141414" stroke-dasharray="${circ}" stroke-dashoffset="${circ*(1-Math.min(t.kcal/s.calorieFloor,1))}"/></svg><div class="ring-center"><span class="tiny-icon">${ic('leaf')}</span><span class="number">${logged?fmt(t.kcal):'—'}</span><span class="muted ring-label">${!logged?'No food logged':'kcal logged'}</span></div></div><div class="nutrition-side"><div class="protein"><div class="stat-row"><span class="muted">Protein</span><strong>${logged?fmt(t.protein):'—'} <span class="muted small">/ ${s.proteinTarget} g</span></strong></div><div class="bar"><span style="width:${Math.min(100,t.protein/s.proteinTarget*100)}%"></span></div></div><div class="stat-row"><span class="muted">Intake floor</span><strong>${fmt(s.calorieFloor)} <span class="muted small">kcal</span></strong></div></div></div><div class="nutri-note meal-status">${ic('info')}<span>${!logged?"No meals logged yet. Add your first meal when you’re ready.":pending.length?`${esc(pending.join(', '))} not logged yet. This is a partial-day total.`:"All meal slots logged. Estimated portions stay marked."}</span></div><div class="mini-stats"><button class="mini-stat text-btn" style="display:block;text-align:left;color:var(--ink);padding:0 10px 0 0" data-action="weight"><span class="label">${ic('scale')} Latest weight</span><strong>${latest?latest.kg.toFixed(1):'—'} <small>kg</small></strong></button><button class="mini-stat text-btn" style="display:block;text-align:left;color:var(--ink);padding:0 10px 0 0" data-action="recovery"><span class="label">${ic('moon')} Sleep</span><strong>${d.sleep??'—'} <small>hours</small></strong></button><div class="mini-stat"><span class="label">${ic('activity')} Movement</span><strong>${completed.reduce((n,x)=>n+x.duration,0)||'—'} <small>min logged</small></strong></div></div></section><section class="card"><div class="card-head"><h2>On your plate</h2><button class="text-btn" data-action="food">${ic('plus')} Log food</button></div>${logged?meals().map(m=>mealRow(m,true)).join(''):`<p class="muted small">Your journal is ready for its first meal.</p>`}${pending.length?`<button class="meal-placeholder" data-action="food"><span class="meal-art">${ic('food')}</span><span><strong>${esc(pending[0])} is still an open page</strong><small>Photo, saved meal, or a quick manual entry</small></span>${ic('plus')}</button>`:''}</section></div><div class="stack"><section class="card"><div class="card-head"><h2>How are you feeling?</h2><button class="text-btn" data-action="recovery">Check in ${ic('chevron')}</button></div><div class="checkin">${['😴','😕','🙂','😊','⚡'].map((m,i)=>`<button class="mood-btn ${d.energy===i+1?'active':''}" data-energy="${i+1}" aria-label="Energy ${i+1} of 5" aria-pressed="${d.energy===i+1}">${m}<small>${['Low','Tired','Okay','Good','Great'][i]}</small></button>`).join('')}</div><p class="checkin-note">Your energy and recovery help shape tomorrow's plan.</p><div class="water-row"><div><span class="small muted">${ic('water')} Water logged</span><div class="water-value" style="margin-top:7px">${d.water.toFixed(2).replace(/0$/,'')} <small>/ ${s.waterTarget} L</small></div></div><button class="btn secondary" data-action="water">${ic('plus')} Log water</button></div></section></div></div><div class="banner">${ic('sun')}<div><strong>Your goal is a direction. Today is a fresh start.</strong><p>Build a routine you can return to. Your plan adapts to what actually happens.</p></div><button class="text-btn" data-nav="progress">See progress ${ic('arrow')}</button></div>`}
function foodView(){const t=totals();const estimated=t.estimated;return `${heading('Good food. Clear picture.','Your meals, portions, and estimates in one place.',`<button class="btn" data-action="food">${ic('plus')} Log food</button>`)}${weekStrip()}<div class="metric-grid"><div class="card metric-card"><span class="eyebrow">Calories logged</span><div class="number">${meals().length?fmt(t.kcal):'—'} <small>kcal</small></div><p class="muted small">${meals().length?`${fmt(t.low)}–${fmt(t.high)} estimated range`:'No confirmed meals'}</p></div><div class="card metric-card"><span class="eyebrow">Protein</span><div class="number">${fmt(t.protein)} <small>g</small></div><p class="muted small">${t.unknownProtein?'Includes unknown protein':'From confirmed entries'}</p></div><div class="card metric-card"><span class="eyebrow">Meal coverage</span><div class="number">${new Set(meals().map(m=>m.slot)).size}<small> / 3 slots</small></div><p class="muted small">${estimated} estimated items</p></div></div><div class="section-grid"><section class="card"><div class="card-head"><h2>Your food journal</h2><span class="badge outline">${pretty(selected)}</span></div>${meals().length?meals().map(m=>mealRow(m,true)).join(''):`<div class="empty">${ic('food')}<h3>Start with your next meal</h3><p>Add a usual meal or enter a portion. Only confirmed entries count toward your day.</p><button class="btn" data-action="food">${ic('plus')} Add your first meal</button></div>`}<button class="meal-placeholder" data-action="photo"><span class="meal-art">${ic('camera')}</span><span><strong>Keep a photo with your meal</strong><small>Upload, add the details, then confirm</small></span>${ic('arrow')}</button></section><section class="card"><div class="card-head"><h2>Your usuals</h2><span class="badge">Quick log</span></div><p class="muted small" style="margin-bottom:18px">Familiar meals. Less typing. Review portions each time.</p>${allPresets().map(p=>presetRow(p)).join('')}<div class="notice green">Your confirmation saves the entry. Estimated portions stay marked as estimated.</div></section></div>`}
function allPresets(){return [...presets,...state.savedPresets]}
function presetRow(p){return `<button class="preset-row" data-preset="${p.id}"><span class="meal-art">${p.emoji||'🍽️'}</span><span><strong>${esc(p.name)}</strong><small>${p.items.length} items · review your serving</small></span>${ic('chevron')}</button>`}
function planView(){const p=currentPlan();return `${heading('Tomorrow has room for you.','A daily plan shaped by your real life.',`<button class="btn secondary" data-action="regenerate">${ic('refresh')} Refresh plan</button>`)}<div class="plan-summary"><span class="badge">${ic('calendar')} ${pretty(offset(today,1),{weekday:'long',month:'short',day:'numeric'})}</span><span class="badge outline">${backend.connected&&p.server_revision===backend.revision?(p.source==='ai'?'AI plan · server validated':'Server-validated template plan'):'Local template preview'}</span><span class="badge outline">${state.settings.availableMinutes} min available</span></div><div class="section-grid"><section class="card"><div class="card-head"><h2>A rhythm for tomorrow</h2><span class="badge">${p.valid?'Validated':'Needs attention'}</span></div>${p.valid?`<div class="timeline">${p.meals.map(m=>`<div class="timeline-item"><span class="timeline-time">${m.time}</span><div class="timeline-content"><h3>${esc(m.slot)} · ${esc(m.name)}</h3><p>${esc(m.detail)}</p><span class="badge outline">~${fmt(m.kcal)} kcal · ${fmt(m.protein)} g protein</span></div></div>`).join('')}<div class="timeline-item"><span class="timeline-time">Flexible</span><div class="timeline-content"><h3>${esc(p.activity?.name||'Recovery time')}</h3><p>${esc(p.activity?.detail||'No planned training. Check in again tomorrow.')}</p><span class="badge">${p.rest?'Recovery first':'Maintain your rhythm'}</span></div></div></div><div class="draft-total"><span>Planned intake · estimated</span><span>~${fmt(p.kcal)} kcal</span></div><p class="footer-note">Calculated from illustrative food values. Actual portions and preparation can change nutrition.</p>`:`<div class="notice">${esc(p.error)}</div><button class="btn secondary" data-nav="settings">Review settings</button>`}</section><div class="stack"><section class="card"><div class="card-head"><h2>Why this plan?</h2>${ic('leaf')}</div><div class="plan-reason"><strong>${p.rest?'Make space for recovery.':'Keep it comfortable and consistent.'}</strong>${esc(p.reason)}</div><p class="muted small">No fixed three-month schedule. Each refresh uses your confirmed logs, check-in and available activities.</p></section><section class="card"><div class="card-head"><h2>Make it fit your day</h2></div><label class="field">Time available tomorrow<select id="available-minutes">${[0,15,30,45,60].map(n=>`<option value="${n}" ${n===state.settings.availableMinutes?'selected':''}>${n===0?'Rest day':`${n} minutes`}</option>`).join('')}</select></label><div class="spacer"></div><button class="btn secondary full" data-action="recovery">${ic('moon')} Update recovery</button><div class="availability"><span>Badminton partner available?</span><button class="toggle ${state.activities.find(a=>a.id==='badminton')?.available?'on':''}" data-partner="badminton" role="switch" aria-checked="${!!state.activities.find(a=>a.id==='badminton')?.available}" aria-label="Badminton partner availability"></button></div><p class="footer-note">You control your goal date. Plans never change it automatically.</p></section></div></div>`}
function activityView(){const sessions=state.sessions.filter(s=>s.date===selected);return `${heading('Move your own way.','Your favorites, your pace, your next small step.',`<button class="btn" data-action="add-activity">${ic('plus')} Add activity</button>`)}<div class="card" style="margin-bottom:22px"><div class="card-head"><h2>${selected===today?"Today's":"Selected day's"} movement</h2><button class="text-btn" data-action="log-session">${ic('plus')} Log session</button></div>${sessions.length?sessions.map(s=>sessionRow(s)).join(''):`<p class="muted small">Nothing logged yet. Planned activities count only when you record what you did.</p>`}</div><div class="section-grid">${state.activities.map(a=>`<section class="card activity-card"><div class="activity-header"><span class="activity-art">${ic(a.icon)}</span><div><h3>${esc(a.name)}</h3><p class="muted small">${esc(a.type)} · ${a.metric==='reps'?'sets & reps':a.metric==='distance'?'distance & time':'duration'}</p></div><button class="toggle ${a.enabled?'on':''}" data-toggle-activity="${a.id}" role="switch" aria-checked="${a.enabled}" aria-label="Enable ${esc(a.name)}"></button></div><p class="muted small">${esc(a.id==='jog'?'Build consistency before chasing speed.':a.id==='bar'?'Track holds, reps and the work you actually do.':a.id==='badminton'?'A social session when your partner is available.':a.id==='walk'?'An easy option for a little everyday movement.':'Your custom activity. Keep the load familiar.')}</p><div class="activity-meta"><span class="badge outline">${a.partner?'Partner needed':'Solo-friendly'}</span><span class="badge outline">Maintain-only</span></div><button class="btn secondary" data-log-activity="${a.id}" ${!a.enabled?'disabled':''}>${ic('plus')} Log ${esc(a.name.toLowerCase())}</button><div class="activity-controls"><select data-preference="${a.id}" aria-label="Preference for ${esc(a.name)}">${['most','mid','least'].map(v=>`<option value="${v}" ${a.preference===v?'selected':''}>${{most:'Most preferred',mid:'Sometimes',least:'Occasionally'}[v]}</option>`).join('')}</select>${!a.partner?`<button class="toggle ${a.available?'on':''}" data-partner="${a.id}" role="switch" aria-checked="${a.available}" aria-label="${esc(a.name)} equipment and time available"></button>`:''}</div>${a.partner?`<div class="availability"><span>Partner confirmed</span><button class="toggle ${a.available?'on':''}" data-partner="${a.id}" role="switch" aria-checked="${a.available}" aria-label="${esc(a.name)} partner available"></button></div>`:`<p class="muted small" style="margin-top:9px">Availability: ${a.available?'ready':'unavailable'}</p>`}</section>`).join('')}</div>`}
function sessionRow(s){const a=state.activities.find(a=>a.id===s.activityId);return `<div class="log-row"><span class="activity-art">${ic(a?.icon||'activity')}</span><div><strong>${esc(s.name)}</strong><small>${s.duration} min${s.distance?` · ${s.distance} km`:''}${s.steps!=null?` · ${fmt(s.steps)} steps`:''}${s.reps?` · ${s.sets||1} × ${s.reps} reps`:''}${s.hold?` · ${s.hold}s holds`:''} · effort ${s.effort}/10 · ${esc(s.status)}</small></div><button class="icon-btn" data-delete-session="${s.id}" aria-label="Delete ${esc(s.name)} session">${ic('trash')}</button></div>`}
function weightChart(){const rows=state.weights.filter(w=>w.date>=offset(today,-viewWeeks+1)&&w.date<=today).sort((a,b)=>a.date.localeCompare(b.date));if(!rows.length)return `<div class="empty">${ic('chart')}<h3>Your story starts here</h3><p>Log a weight to begin your trend. Missing days won't be filled in.</p></div>`;const low=Math.floor(Math.min(...rows.map(r=>r.kg))*2)/2-.3,high=Math.ceil(Math.max(...rows.map(r=>r.kg))*2)/2+.3;const point=r=>[45+((new Date(r.date)-new Date(offset(today,-viewWeeks+1)))/(86400000*Math.max(1,viewWeeks-1)))*485,25+(high-r.kg)/(high-low)*135];const points=rows.map(point);const d=points.map((p,i)=>`${i?'L':'M'}${p[0]},${p[1]}`).join(' ');return `<svg class="chart" viewBox="0 0 560 205" role="img" aria-label="Weight measurements over the last ${viewWeeks} days"><defs><linearGradient id="area" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stop-color="#d4d8d6" stop-opacity=".7"/><stop offset="100%" stop-color="#d4d8d6" stop-opacity="0"/></linearGradient></defs>${[0,.5,1].map(f=>`<line x1="45" y1="${25+f*135}" x2="530" y2="${25+f*135}" stroke="#e9ece4" stroke-dasharray="4 4"/><text x="4" y="${29+f*135}">${(high-f*(high-low)).toFixed(1)}</text>`).join('')}<path d="${d} L${points.at(-1)[0]},160 L${points[0][0]},160Z" fill="url(#area)"/><path d="${d}" fill="none" stroke="#111111" stroke-width="2.5" stroke-linejoin="round"/>${points.map((p,i)=>`<circle cx="${p[0]}" cy="${p[1]}" r="4" stroke="white" stroke-width="2" fill="#111111"><title>${rows[i].date}: ${rows[i].kg} kg</title></circle>`).join('')}<text x="45" y="190">${pretty(offset(today,-viewWeeks+1))}</text><text x="500" y="190">Today</text></svg>`}
function progressView(){const trend=weightTrend(state.weights,today);const last=state.weights.filter(w=>w.date<=today).sort((a,b)=>a.date.localeCompare(b.date)).at(-1);const changeKg=last?state.settings.startWeight-last.kg:null;const percent=last?Math.max(0,Math.min(100,(state.settings.startWeight-last.kg)/(state.settings.startWeight-state.settings.targetWeight)*100)):0;const recent=state.sessions.filter(s=>s.date>=offset(today,-6)&&s.date<=today);return `${heading('Progress, beyond a number.','Look at the pattern. Give the day-to-day some space.',`<button class="btn" data-action="weight">${ic('plus')} Log weight</button>`)}<div class="metric-grid"><section class="card metric-card"><span class="eyebrow">Latest weight</span><div class="number">${last?last.kg.toFixed(1):'—'} <small>kg</small></div><p class="muted small">${last?pretty(last.date):'No measurements yet'}</p></section><section class="card metric-card"><span class="eyebrow">7-day average</span><div class="number">${trend.avg!==null?trend.avg.toFixed(1):'—'} <small>kg</small></div><p class="muted small">${trend.count} measurements · ${trend.count<3?'sparse data':'observed samples'}</p></section><section class="card metric-card"><span class="eyebrow">From start</span><div class="number">${changeKg===null?'—':`${changeKg>0?'−':changeKg<0?'+':''}${Math.abs(changeKg).toFixed(1)}`} <small>kg</small></div><p class="muted small">Start: ${state.settings.startWeight} kg</p></section></div><div class="section-grid"><section class="card reflection-first"><div class="card-head"><h2>This week's reflection</h2>${backend.connected?`<button class="text-btn" data-action="weekly-review">Review now ${ic('refresh')}</button>`:'<span class="badge outline">Local summary</span>'}</div><p class="muted" style="font-size:13px;line-height:1.8">${trend.count?`You have ${trend.count} weight measurements this week. `:'Start with a few weight measurements. '}${recent.length?`You've logged ${recent.length} movement sessions. `:'A logged walk is a useful starting point. '} Keep portions and recovery visible so your next plan has better context.</p><div class="notice green">More complete logs help explain your routine. They don't prove the cause of weight changes.</div></section><section class="card"><div class="card-head"><h2>Weight, in perspective</h2><select id="chart-range" aria-label="Chart date range" style="border:1px solid var(--line);padding:8px;border-radius:9px;background:white;font-size:11px"><option value="7" ${viewWeeks===7?'selected':''}>7 days</option><option value="30" ${viewWeeks===30?'selected':''}>30 days</option></select></div><div class="chart-wrap">${weightChart()}</div><p class="muted small">Each point is a logged measurement. A single day doesn't define your progress.</p></section><section class="card"><div class="card-head"><h2>A direction to work toward</h2>${ic('leaf')}</div><div style="display:flex;justify-content:space-between;align-items:flex-end;margin:26px 0 15px"><div><span class="eyebrow">Your goal</span><div class="number" style="font-size:36px;font-weight:750;margin-top:7px">${state.settings.targetWeight} <span class="muted" style="font-size:14px">kg</span></div></div><span class="badge">${Math.round(percent)}% of weight gap</span></div><div class="bar"><span style="width:${percent}%"></span></div><div class="stat-row" style="margin-top:20px"><span class="muted">Target date</span><strong>${pretty(state.settings.endDate,{day:'numeric',month:'short',year:'numeric'})}</strong></div><p class="muted small" style="margin-top:15px">The date is yours to review. Your daily plan never moves it automatically.</p><button class="text-btn" data-nav="settings" style="margin-top:15px">Review your goal ${ic('arrow')}</button></section><section class="card"><div class="card-head"><h2>A week of movement</h2><span class="badge">${recent.length} sessions</span></div><div class="number" style="font-size:29px;font-weight:750">${recent.reduce((n,s)=>n+s.duration,0)} <span class="muted" style="font-size:12px">minutes logged</span></div><div class="week-activity">${Array.from({length:7},(_,i)=>{const date=offset(today,i-6);const min=recent.filter(s=>s.date===date).reduce((n,s)=>n+s.duration,0);return `<div class="week-column"><div class="column" style="height:${Math.max(4,Math.min(55,min))}px" title="${min} minutes"></div><small>${pretty(date,{weekday:'narrow'})}</small></div>`}).join('')}</div><p class="footer-note">Only actual sessions count. Partial sessions count too.</p></section></div><section class="card" style="margin-top:20px"><div class="card-head"><h2>Measurements</h2></div>${state.weights.length?state.weights.slice().sort((a,b)=>b.date.localeCompare(a.date)).slice(0,30).map(w=>`<div class="log-row"><div><strong>${w.kg.toFixed(1)} kg</strong><small>${pretty(w.date,{day:'numeric',month:'short',year:'numeric'})}</small></div><button class="icon-btn" data-delete-weight="${w.date}" aria-label="Remove weight on ${w.date}">${ic('trash')}</button></div>`).join(''):'<p class="muted small">No measurements yet.</p>'}</section>`}
function settingsView(){const s=state.settings;return `${heading('Make this space yours.','Your goal, your routine, and the things that matter to you.')}<div class="settings-stack"><form id="settings-form"><section class="card"><div class="card-head"><h2>Your starting point</h2>${ic('leaf')}</div><div class="form-grid"><label class="field full-field">First name<input name="name" value="${esc(s.name)}" required maxlength="40"></label><label class="field">Starting weight (kg)<input type="number" name="startWeight" value="${s.startWeight}" min="20" max="400" step="0.1" required></label><label class="field">Goal weight (kg)<input type="number" name="targetWeight" value="${s.targetWeight}" min="20" max="400" step="0.1" required></label><label class="field full-field">Goal date<input type="date" name="endDate" value="${s.endDate}" min="${offset(today,1)}" required></label></div><p class="footer-note">An initial horizon, not a fixed schedule. You decide when to change your goal.</p></section><section class="card" style="margin-top:20px"><div class="card-head"><h2>Food & daily rhythm</h2>${ic('food')}</div><div class="form-grid"><label class="field">Intake floor (kcal)<input type="number" name="calorieFloor" value="${s.calorieFloor}" min="500" max="5000" step="10" required></label><label class="field">Protein reference (g)<input type="number" name="proteinTarget" value="${s.proteinTarget}" min="10" max="300" required></label><label class="field">Water reference (L)<input type="number" name="waterTarget" value="${s.waterTarget}" min="0.25" max="8" step="0.25" required></label><label class="field">Time available (min)<select name="availableMinutes">${[0,15,30,45,60].map(n=>`<option value="${n}" ${s.availableMinutes===n?'selected':''}>${n}</option>`).join('')}</select></label>${Object.entries(s.mealTimes).map(([slot,time])=>`<label class="field">${slot} time<input type="time" name="time_${slot}" value="${time}" required></label>`).join('')}</div><label class="check-label"><input type="checkbox" name="fasting" ${s.fasting?'checked':''}> Use an eating window</label><div class="form-grid" style="margin-top:15px"><label class="field">Eating window starts<input type="time" name="eatFrom" value="${s.eatFrom}" required></label><label class="field">Eating window ends<input type="time" name="eatUntil" value="${s.eatUntil}" required></label></div><p class="footer-note">These references are user settings, not personalized recommendations. Planned meals must respect the configured floor.</p><p id="settings-error" class="notice" hidden></p><div class="form-actions"><button class="btn full" type="submit">${ic('check')} Save preferences</button></div></section></form><section class="card"><div class="card-head"><h2>AI connections</h2><span class="badge outline">${backend.connected?'Python service connected':'Not connected'}</span></div><div class="settings-row"><div><strong>Gemini · photo recognition</strong><p>${backend.connected&&backend.capabilities.gemini?'Photo recognition is ready. Choose Analyze after attaching a photo.':'Photo attachments and manual review are available. Recognition needs server credentials.'}</p></div>${ic('camera')}</div><div class="settings-row"><div><strong>DeepSeek · daily planning</strong><p>${backend.connected&&backend.capabilities.deepseek?'AI planning is ready. Enable it below, then refresh your plan.':'Template planning is available. AI planning needs server credentials.'}</p></div>${ic('calendar')}</div>${backend.connected&&backend.capabilities.deepseek?`<label class="check-label"><input type="checkbox" id="use-ai" ${useAI?'checked':''}> Use DeepSeek when refreshing my plan</label>`:''}<p class="footer-note">API keys are never requested or stored in this browser.</p></section><section class="card"><div class="card-head"><h2>Your journal data</h2><span class="badge outline">${backend.connected?'Server + browser backup':'Browser storage'}</span></div><p class="muted small">${backend.connected?'Your journal saves to the Python server for this anonymous browser session. Export a backup for transfer to another device.':'Entries stay on this browser and do not sync between devices. Export a backup whenever you need one.'}</p><div class="form-actions"><button class="btn secondary" data-action="protection">Recovery & backups</button><button class="btn secondary" data-action="recover-journal">Recover journal</button></div><div class="form-actions"><button class="btn secondary" data-action="export">${ic('download')} Export JSON</button><button class="btn secondary" data-action="import">Import backup</button></div><div class="form-actions"><button class="btn ${state.demo?'':'secondary'}" data-action="fresh">Start fresh</button><button class="btn secondary" data-action="sample">Load sample data</button></div></section></div>`}
function bindView(){const aiToggle=document.querySelector('#use-ai');if(aiToggle)aiToggle.onchange=()=>{useAI=aiToggle.checked};bindSearch();const dateInput=document.querySelector('#journal-date');if(dateInput)dateInput.onchange=()=>{if(dateInput.value&&dateInput.value<=today){selected=dateInput.value;render()}};document.querySelectorAll('[data-nav]').forEach(b=>b.onclick=()=>nav(b.dataset.nav));document.querySelectorAll('[data-date]').forEach(b=>b.onclick=()=>{selected=b.dataset.date;render()});document.querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>action(b.dataset.action));document.querySelectorAll('[data-energy]').forEach(b=>b.onclick=()=>{dayUpdate('energy',Number(b.dataset.energy));toast('Energy check-in saved')});document.querySelectorAll('[data-preset]').forEach(b=>b.onclick=()=>loadPreset(b.dataset.preset));document.querySelectorAll('[data-edit-meal]').forEach(b=>b.onclick=()=>editMealOpen(b.dataset.editMeal));document.querySelectorAll('[data-delete-meal]').forEach(b=>b.onclick=()=>deleteMeal(b.dataset.deleteMeal));document.querySelectorAll('[data-toggle-activity]').forEach(b=>b.onclick=()=>{const a=state.activities.find(a=>a.id===b.dataset.toggleActivity);a.enabled=!a.enabled;change()});document.querySelectorAll('[data-partner]').forEach(b=>b.onclick=()=>{const a=state.activities.find(a=>a.id===b.dataset.partner);if(a){a.available=!a.available;change()}});document.querySelectorAll('[data-preference]').forEach(b=>b.onchange=()=>{state.activities.find(a=>a.id===b.dataset.preference).preference=b.value;change()});document.querySelectorAll('[data-log-activity]').forEach(b=>b.onclick=()=>sessionSheet(b.dataset.logActivity));document.querySelectorAll('[data-delete-session]').forEach(b=>b.onclick=()=>confirmSheet('Remove this session?','This removes the logged activity from your journal.',()=>{state.sessions=state.sessions.filter(s=>s.id!==b.dataset.deleteSession);change();toast('Session removed')}));document.querySelectorAll('[data-delete-weight]').forEach(b=>b.onclick=()=>confirmSheet('Remove this measurement?','This measurement will be removed from your trend.',()=>{state.weights=state.weights.filter(w=>w.date!==b.dataset.deleteWeight);change()}));const available=document.querySelector('#available-minutes');if(available)available.onchange=()=>{state.settings.availableMinutes=Number(available.value);change();toast('Tomorrow’s availability updated')};const range=document.querySelector('#chart-range');if(range)range.onchange=()=>{viewWeeks=Number(range.value);render()};const form=document.querySelector('#settings-form');if(form)form.onsubmit=saveSettings;}
function action(a){({'help':helpSheet,'quick-add':quickAdd,water:()=>waterSheet(selected),'water-today':()=>waterSheet(today),'updates':updatesSheet,'weekly-review':weeklyReviewSheet,'protection':protectionSheet,'recover-journal':recoverJournalSheet,food:()=>foodSheet('manual'),photo:()=>foodSheet('photo'),weight:weightSheet,recovery:recoverySheet,'add-activity':activitySheet,'log-session':()=>sessionSheet(),regenerate:()=>{if(backend.connected){refreshServerPlan(useAI);return}state.plan={...buildPlan(state,today),revision:state.revision};persist();render();toast('Plan refreshed from your latest logs')},export:exportData,import:importData,fresh:()=>confirmSheet('Start your own journal?','This clears the sample or existing entries and keeps your preferences. Export a backup first if you need it.',()=>{const settings=state.settings;state=seed(false);state.settings=settings;persist();selected=today;render();toast('Your fresh journal is ready')}),sample:()=>confirmSheet('Load sample data?','This replaces the current journal with clearly labeled example entries. Export a backup first if needed.',()=>{state=seed(true);persist();selected=today;render();toast('Sample journal loaded')})})[a]?.()}
const sheet=document.querySelector('#sheet');function openSheet(title,sub,html){document.querySelector('#sheet-content').innerHTML=`<div class="sheet-head"><h2>${title}</h2><button class="icon-btn" id="close-sheet" aria-label="Close dialog">${ic('close')}</button></div><p class="sheet-sub">${sub}</p>${html}`;document.querySelector('#close-sheet').onclick=()=>sheet.close();if(!sheet.open)sheet.showModal();sheet.setAttribute('aria-label',title);}
sheet.addEventListener('click',e=>{if(e.target===sheet){const r=sheet.getBoundingClientRect();if(e.clientY<r.top||e.clientY>r.bottom||e.clientX<r.left||e.clientX>r.right)sheet.close()}});
function confirmSheet(title,sub,fn){openSheet(title,sub,`<div class="form-actions"><button class="btn secondary" id="cancel-confirm">Cancel</button><button class="btn" id="yes-confirm">Confirm</button></div>`);document.querySelector('#cancel-confirm').onclick=()=>sheet.close();document.querySelector('#yes-confirm').onclick=()=>{sheet.close();fn()}}
function weightSheet(){openSheet('One measurement.','Log a weight. The trend matters more than a single number.',`<form id="weight-form"><div class="form-grid"><label class="field">Date<input type="date" name="date" value="${selected}" max="${today}" required></label><label class="field">Weight (kg)<input type="number" name="kg" min="20" max="400" step="0.1" placeholder="75.6" required></label></div><div class="form-actions"><button class="btn full">${ic('check')} Save measurement</button></div></form>`);document.querySelector('#weight-form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target);state.weights=state.weights.filter(w=>w.date!==f.get('date'));state.weights.push({date:f.get('date'),kg:Number(f.get('kg'))});state.weights.sort((a,b)=>a.date.localeCompare(b.date));sheet.close();change();toast('Weight saved')}}
function waterSheet(date=selected){
  const d=state.days[date]||{energy:null,water:0,sleep:null,soreness:'none'};
  const total=Math.round(d.water*1000);
  openSheet('A little hydration.','Log water for '+(date===today?'today':pretty(date))+'.',`<div class="water-summary"><strong>${total.toLocaleString()} <small>ml logged</small></strong><span class="muted small">Your reference: ${Math.round(state.settings.waterTarget*1000).toLocaleString()} ml</span></div><div class="water-presets">${[250,500,750].map(ml=>`<button class="btn secondary" type="button" data-water-amount="${ml}">${ic('water')}<strong>+${ml}</strong><small>ml</small></button>`).join('')}</div><details class="water-custom"><summary>Custom amount or edit total</summary><form id="water-form"><label class="field">Amount (ml)<input name="amount" type="number" inputmode="numeric" min="0" max="10000" step="1" value="250" required></label><div class="form-actions"><button class="btn" type="submit" value="add">Add water</button><button class="btn secondary" type="submit" value="set">Set daily total</button></div><p class="muted small">Set daily total replaces the amount already logged for this date.</p></form></details><p class="notice" id="water-error" role="alert" hidden></p>`);
  const save=(ml,replace=false)=>{
    const current=state.days[date]||d;
    const next=replace?ml:Math.round(current.water*1000)+ml;
    if(!Number.isInteger(ml)||ml<0||(!replace&&ml===0)||next>10000){const error=document.querySelector('#water-error');error.textContent='Enter a valid amount. The journal supports a daily total from 0 to 10,000 ml.';error.hidden=false;return;}
    state.days[date]={...current,water:next/1000};sheet.close();change();toast(replace?'Water total updated':`${ml} ml water added`);
  };
  document.querySelectorAll('[data-water-amount]').forEach(button=>button.onclick=()=>save(Number(button.dataset.waterAmount)));
  document.querySelector('#water-form').onsubmit=e=>{e.preventDefault();save(Number(new FormData(e.target).get('amount')),e.submitter?.value==='set');};
}
function recoverySheet(){const d=getDay();openSheet('A moment to check in.','Your actual recovery shapes the next plan.',`<form id="recovery-form"><div class="form-grid"><label class="field">Sleep (hours)<input type="number" name="sleep" min="0" max="24" step="0.5" value="${d.sleep??''}" placeholder="Leave blank if unknown"></label><label class="field">Energy<select name="energy"><option value="">Not logged</option>${[1,2,3,4,5].map(v=>`<option value="${v}" ${d.energy===v?'selected':''}>${v} · ${['Low','Tired','Okay','Good','Great'][v-1]}</option>`).join('')}</select></label><label class="field full-field">Soreness / discomfort<select name="soreness">${['none','legs','upper body','pain'].map(v=>`<option value="${v}" ${d.soreness===v?'selected':''}>${{none:'None reported',legs:'Leg soreness','upper body':'Upper-body soreness',pain:'Pain / exercise discomfort'}[v]}</option>`).join('')}</select></label></div><div class="form-actions"><button class="btn full">${ic('check')} Save check-in</button></div></form>`);document.querySelector('#recovery-form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target);state.days[selected]={...getDay(),sleep:f.get('sleep')===''?null:Number(f.get('sleep')),energy:f.get('energy')===''?null:Number(f.get('energy')),soreness:f.get('soreness')};sheet.close();change();toast('Recovery check-in saved')}}
function activitySheet(){openSheet('A new way to move.','Add an activity to your library. Custom sessions maintain a familiar load.',`<form id="activity-form"><div class="form-grid"><label class="field full-field">Activity name<input name="name" placeholder="Cycling, swimming, yoga…" maxlength="50" required></label><label class="field">Type<select name="type"><option>cardio</option><option>strength</option><option>sport</option><option>mobility</option></select></label><label class="field">Track by<select name="metric"><option value="duration">Duration</option><option value="distance">Distance & time</option><option value="reps">Sets & reps / holds</option></select></label><label class="field full-field">Preference<select name="preference"><option value="most">Most preferred</option><option value="mid" selected>Sometimes</option><option value="least">Occasionally</option></select></label></div><label class="check-label"><input type="checkbox" name="partner"> Requires a partner</label><div class="form-actions"><button class="btn full">${ic('plus')} Add to library</button></div></form>`);document.querySelector('#activity-form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target);const name=f.get('name').trim();if(!name)return;const partner=f.get('partner')==='on';state.activities.push({id:id(),name,type:f.get('type'),metric:f.get('metric'),preference:f.get('preference'),icon:'activity',enabled:true,partner,available:!partner});sheet.close();change();toast('Activity added')}}
function sessionSheet(activityId){const options=state.activities.filter(a=>a.enabled);if(!options.length){toast('Enable an activity first');return}const a=options.find(a=>a.id===activityId)||options[0];openSheet('Log what you did.','Every completed or partial session is useful context.',`<form id="session-form"><div class="form-grid"><label class="field full-field">Activity<select name="activity" id="session-activity">${options.map(o=>`<option value="${o.id}" ${o.id===a.id?'selected':''}>${esc(o.name)}</option>`).join('')}</select></label><label class="field">Date<input type="date" name="date" max="${today}" value="${selected}" required></label><label class="field">Duration (min)<input type="number" name="duration" min="1" max="600" value="20" required></label><div id="metric-fields" class="field full-field"></div><label class="field">Effort (1–10)<input type="number" name="effort" min="1" max="10" value="5" required></label><label class="field">Completion<select name="status"><option value="completed">Completed</option><option value="partial">Partial session</option></select></label></div><div class="form-actions"><button class="btn full">${ic('check')} Save session</button></div></form>`);const metrics=()=>{const o=state.activities.find(o=>o.id===document.querySelector('#session-activity').value);document.querySelector('#metric-fields').innerHTML=o.metric==='distance'?`<label class="field">Distance (km)<input type="number" name="distance" min="0.1" max="200" step="0.1" required></label>`:o.metric==='reps'?`<div class="form-grid"><label class="field">Sets<input name="sets" type="number" min="1" max="100" value="3"></label><label class="field">Reps per set<input name="reps" type="number" min="0" max="1000" value="0"></label><label class="field full-field">Hold per set (seconds, optional)<input name="hold" type="number" min="0" max="3600" placeholder="20"></label></div>`:'';if(o.id==='walk'||o.icon==='walk'||/^(walk|walking)$/i.test(o.name.trim()))document.querySelector('#metric-fields').insertAdjacentHTML('beforeend',`<label class="field">Steps (optional)<input name="steps" type="number" inputmode="numeric" min="0" max="200000" step="1" placeholder="e.g. 3000"></label>`)};metrics();document.querySelector('#session-activity').onchange=metrics;document.querySelector('#session-form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target),o=state.activities.find(a=>a.id===f.get('activity'));if(o.metric==='reps'&&Number(f.get('reps'))===0&&Number(f.get('hold'))===0){toast('Enter reps or a hold duration');return}state.sessions.push({id:id(),date:f.get('date'),activityId:o.id,name:o.name,duration:Number(f.get('duration')),effort:Number(f.get('effort')),distance:Number(f.get('distance'))||null,steps:f.get('steps')===null||f.get('steps')===''?null:Number(f.get('steps')),sets:Number(f.get('sets'))||null,reps:Number(f.get('reps'))||null,hold:Number(f.get('hold'))||null,status:f.get('status')});sheet.close();change();toast('Session saved · your next plan will adapt')}}
function foodSheet(tab='manual',keep=false){if(!keep){draft=[];draftPhoto=null;editMeal=null;activePhotoDraft=null;draftNotice=''}foodTab=tab;drawFoodSheet();}
function loadPreset(presetId){const p=allPresets().find(p=>p.id===presetId);if(!p)return;draft=p.items.map(i=>i.food?foodItem(i.food,i.amount):{...structuredClone(i),id:id()});draftPhoto=null;editMeal=null;activePhotoDraft=null;draftNotice='';foodTab='review';drawFoodSheet()}
function deleteMeal(mealId){
  const meal=state.meals.find(m=>m.id===mealId);if(!meal)return;
  confirmSheet('Delete '+esc(meal.slot)+'?','This removes the meal from your journal and updates your daily totals.',()=>{
    state.meals=state.meals.filter(m=>m.id!==mealId);editMeal=null;draft=[];activePhotoDraft=null;change();toast('Meal deleted');
  });
}
function editMealOpen(mealId){const m=state.meals.find(m=>m.id===mealId);draft=structuredClone(m.items);editMeal=m;draftPhoto=null;activePhotoDraft=null;draftNotice='';foodTab='review';drawFoodSheet()}
function drawFoodSheet(){const tabs=`<div class="tabs">${[['manual','Manual'],['presets','Usual meals'],['photo','Photo']].map(([v,n])=>`<button type="button" data-food-tab="${v}" class="${foodTab===v?'active':''}">${n}</button>`).join('')}</div>`;let content='';if(foodTab==='presets')content=allPresets().map(p=>presetRow(p)).join('');if(foodTab==='photo')content=`<label class="photo-zone">${ic('camera')}<strong>Add a food photo</strong><small>Attach a photo, then enter the meal details.<br>${backend.connected&&backend.capabilities.gemini?'Gemini can recognize the food when you choose Analyze.':'Gemini recognition is not configured.'}</small><input id="photo-file" type="file" accept="image/*" style="max-width:100%;font-size:11px;margin-top:8px"></label>${draftPhoto?`<img class="photo-preview" src="${draftPhoto}" alt="Your attached meal"><div class="notice green">${backend.connected&&backend.capabilities.gemini?'Photo ready. Analyze it, then review every portion.':'Photo attached for manual review. It is not stored after confirmation.'}</div>`:''}${draftPhoto&&backend.connected&&backend.capabilities.gemini?`<button class="btn full" id="analyze-photo" style="margin-bottom:10px">${ic('scan')} Analyze with Gemini</button>`:''}<button class="btn secondary full" id="enter-photo-details">${ic('food')} Enter meal details</button>`;if(foodTab==='manual')content=`<form id="add-food-form"><div class="form-grid"><label class="field full-field">Food<select name="food" id="food-select">${catalog.map(c=>`<option value="${c.id}">${esc(c.name)}</option>`).join('')}<option value="custom">Custom food / label values</option></select></label><div id="food-inputs" class="field full-field"></div></div><div class="form-actions"><button class="btn secondary full">${ic('plus')} Add to draft</button></div></form>`;
const draftHTML=draft.length?`<div class="spacer"></div><h3>Review your meal <span class="badge outline">Draft</span></h3>${draft.map((i,n)=>`<div class="draft-item"><div class="draft-item-head"><strong>${esc(i.name)}</strong><span class="badge warm">Estimated</span><button class="icon-btn" data-remove-item="${n}" aria-label="Remove ${esc(i.name)}">${ic('close')}</button></div><div class="form-grid"><label class="field">Portion (${esc(i.unit)})<input data-portion="${n}" type="number" min="0.1" max="10000" step="0.1" value="${i.amount}"></label><label class="field">Calories (kcal)<input data-calories="${n}" type="number" min="0" max="10000" step="1" value="${i.kcal}"></label></div><p class="muted small" style="margin-top:9px">~${fmt(i.low)}–${fmt(i.high)} kcal · ${i.protein===null?'protein unknown':`${fmt(i.protein)} g protein`} · ${i.food?'catalog average':'manual estimate'}</p></div>`).join('')}<button class="text-btn" id="more-food">${ic('plus')} Add another food</button><div class="draft-total"><span>Meal total · estimated</span><span>${fmt(summarizeMeals([{items:draft}]).kcal)} kcal</span></div><form id="confirm-meal-form"><div class="form-grid" style="margin-top:18px"><label class="field">Meal slot<select name="slot">${Object.keys(state.settings.mealTimes).map(s=>`<option ${editMeal?.slot===s?'selected':''}>${s}</option>`).join('')}</select></label><label class="field">Date<input type="date" name="date" value="${editMeal?.date||selected}" max="${today}" required></label></div><label class="check-label"><input type="checkbox" name="savePreset"> Save as a usual meal</label><div class="form-actions">${editMeal?'<button class="btn danger" type="button" id="delete-meal">Remove meal</button>':''}<button class="btn" type="submit">${ic('check')} ${editMeal?'Save changes':'Confirm meal'}</button></div></form>`:'';
openSheet(editMeal?'Review your meal.':'Make room for a good meal.','Only confirmed entries enter your daily totals. You can change any portion.',tabs+content+(draftNotice?`<div class="notice">${esc(draftNotice)}</div>`:'')+draftHTML);document.querySelectorAll('[data-food-tab]').forEach(b=>b.onclick=()=>{foodTab=b.dataset.foodTab;drawFoodSheet()});document.querySelectorAll('[data-preset]').forEach(b=>b.onclick=()=>loadPreset(b.dataset.preset));const addForm=document.querySelector('#add-food-form');if(addForm){const inputFields=()=>{const selectedFood=document.querySelector('#food-select').value,c=catalog.find(c=>c.id===selectedFood);document.querySelector('#food-inputs').innerHTML=c?`<div class="form-grid"><label class="field">Amount (${c.unit})<input name="amount" type="number" min="0.1" max="10000" step="0.1" value="${c.amount}" required></label><label class="field">Portion source<select name="quality"><option value="manual_estimate">Estimated portion</option><option value="weighed">Weighed portion</option></select></label></div><p class="muted small" style="margin-top:7px">Illustrative catalog average · ${c.kcal} kcal per ${c.basis} ${c.unit}. Preparation matters.</p>`:`<div class="form-grid"><label class="field full-field">Food / preparation<input name="name" maxlength="80" placeholder="Ayam bakar, marinade included" required></label><label class="field">Serving amount<input name="amount" type="number" min="0.1" max="10000" step="0.1" value="1" required></label><label class="field">Unit<select name="unit"><option>serving</option><option>g</option><option>ml</option><option>unit</option></select></label><label class="field">Calories for this portion<input name="kcal" type="number" min="1" max="10000" required></label><label class="field">Protein (g, optional)<input name="protein" type="number" min="0" max="1000" step="0.1"></label></div><p class="muted small">Enter values for the whole portion above. It stays marked as an estimate.</p>`};inputFields();document.querySelector('#food-select').onchange=inputFields;addForm.onsubmit=e=>{e.preventDefault();const f=new FormData(e.target);let item;if(f.get('food')==='custom'){const k=Number(f.get('kcal'));item={id:id(),food:null,name:f.get('name').trim(),unit:f.get('unit'),amount:Number(f.get('amount')),kcal:k,low:Math.round(k*.8),high:Math.round(k*1.2),protein:f.get('protein')===''?null:Number(f.get('protein')),quality:'manual_estimate',emoji:'🍽️'}}else{item=foodItem(f.get('food'),Number(f.get('amount')));item.quality=f.get('quality')}draft.push(item);foodTab='review';drawFoodSheet()}}
const analyzeButton=document.querySelector('#analyze-photo');if(analyzeButton)analyzeButton.onclick=async()=>{analyzeButton.disabled=true;analyzeButton.textContent='Analyzing…';try{const result=await backend.analyze(draftPhoto);activePhotoDraft=result.id;draft=result.items;draftNotice=[...result.unresolved.map(i=>`${i.name}: ${i.reason}`),...result.missing].join(' · ');if(!draft.length&&!draftNotice)draftNotice='No food recognized. Add the meal manually.';foodTab=draft.length?'review':'manual';drawFoodSheet();}catch(e){draftNotice=e.message;drawFoodSheet();}};const photo=document.querySelector('#photo-file');if(photo)photo.onchange=async()=>{const f=photo.files[0];if(!f)return;if(!f.type.startsWith('image/')){toast('Choose an image file');return}if(f.size>15*1024*1024){toast('Choose a photo smaller than 15 MB');return}const reader=new FileReader();reader.onload=()=>{draftPhoto=reader.result;drawFoodSheet()};reader.readAsDataURL(f)};const enter=document.querySelector('#enter-photo-details');if(enter)enter.onclick=()=>{foodTab='manual';drawFoodSheet()};document.querySelectorAll('[data-remove-item]').forEach(b=>b.onclick=()=>{draft.splice(Number(b.dataset.removeItem),1);drawFoodSheet()});document.querySelectorAll('[data-portion]').forEach(input=>input.onchange=()=>{if(!input.checkValidity()){input.reportValidity();return}const i=draft[Number(input.dataset.portion)],ratio=Number(input.value)/i.amount;i.amount=Number(input.value);i.kcal=Math.round(i.kcal*ratio);i.low=Math.round(i.low*ratio);i.high=Math.round(i.high*ratio);if(i.protein!==null)i.protein=+(i.protein*ratio).toFixed(1);drawFoodSheet()});document.querySelectorAll('[data-calories]').forEach(input=>input.onchange=()=>{if(!input.checkValidity()){input.reportValidity();return}const i=draft[Number(input.dataset.calories)];i.kcal=Number(input.value);i.low=Math.round(i.kcal*.8);i.high=Math.round(i.kcal*1.2);i.food=null;i.quality='manual_estimate';drawFoodSheet()});const more=document.querySelector('#more-food');if(more)more.onclick=()=>{foodTab='manual';drawFoodSheet()};const confirm=document.querySelector('#confirm-meal-form');if(confirm)confirm.onsubmit=async e=>{e.preventDefault();if(!draft.length)return;const f=new FormData(e.target);if(activePhotoDraft&&backend.connected){const submit=e.target.querySelector('button[type=submit]');submit.disabled=true;try{const result=await backend.confirm(activePhotoDraft,f.get('date'),f.get('slot'),draft);state=result.state;if(f.get('savePreset')){state.savedPresets.push({id:id(),name:draft.map(i=>i.name.split(' · ')[0]).join(' + '),emoji:draft[0].emoji,items:structuredClone(draft)});state.revision++;persist();}else{hydrating=true;persist();hydrating=false;}activePhotoDraft=null;sheet.close();draft=[];render();await refreshServerPlan(false);toast('Meal confirmed and saved to server');}catch(error){submit.disabled=false;toast(error.message)}return;}const m={id:editMeal?.id||id(),date:f.get('date'),slot:f.get('slot'),items:structuredClone(draft)};if(editMeal)state.meals=state.meals.filter(m=>m.id!==editMeal.id);state.meals.push(m);if(f.get('savePreset'))state.savedPresets.push({id:id(),name:draft.map(i=>i.name.split(' · ')[0]).join(' + '),emoji:draft[0].emoji,items:structuredClone(draft)});sheet.close();draft=[];editMeal=null;change();toast('Meal confirmed · estimates preserved')};const del=document.querySelector('#delete-meal');if(del)del.onclick=()=>{deleteMeal(editMeal.id)};}
function saveSettings(e){e.preventDefault();const f=new FormData(e.target);const next={...state.settings,name:f.get('name').trim(),startWeight:Number(f.get('startWeight')),targetWeight:Number(f.get('targetWeight')),endDate:f.get('endDate'),calorieFloor:Number(f.get('calorieFloor')),proteinTarget:Number(f.get('proteinTarget')),waterTarget:Number(f.get('waterTarget')),availableMinutes:Number(f.get('availableMinutes')),fasting:f.get('fasting')==='on',eatFrom:f.get('eatFrom'),eatUntil:f.get('eatUntil'),mealTimes:Object.fromEntries(['Lunch','Snack','Dinner'].map(s=>[s,f.get('time_'+s)]))};const err=document.querySelector('#settings-error');let message='';if(!next.name)message='Enter a first name.';else if(next.targetWeight>=next.startWeight)message='For this weight-loss goal, choose a target below the starting weight.';else if(next.endDate<=today)message='Choose a future goal date.';else if(next.fasting&&(next.eatFrom>=next.eatUntil||Object.values(next.mealTimes).some(t=>t<next.eatFrom||t>next.eatUntil)))message='All meal times must fit inside the eating window. Overnight windows are not supported yet.';if(message){err.textContent=message;err.hidden=false;return}state.settings=next;state.plan=null;change();toast('Preferences saved · next plan updated')}
async function protectionSheet(){
  openSheet('Recovery & backups.','A spare key for your journal, plus server snapshots.','<p class="muted">Checking protection…</p>');
  try{
    if(!backend.connected)throw new Error('Connect to the Python server to create a recovery code. You can still export your journal.');
    const status=await backend.request('protection');
    const last=status.backup.last_success?new Date(status.backup.last_success).toLocaleString():'No successful backup yet';
    openSheet('Recovery & backups.','Save your recovery code somewhere outside this browser.',`<div class="notice">${status.recovery_enabled?'A recovery code exists. Creating another invalidates the previous code.':'Create a code before clearing cookies or moving to another device.'} Anyone with your code can open this journal.</div><button class="btn full" id="create-recovery">${status.recovery_enabled?'Replace recovery code':'Create recovery code'}</button><div class="settings-row"><div><strong>Latest server backup</strong><p>${esc(last)}</p><p>Every ${esc(status.backup_interval_hours)} hours while the server runs, plus startup. Latest ${esc(status.backup_retention)} snapshots retained.</p></div></div>${status.backup.error?`<div class="notice">${esc(status.backup.error)}</div>`:''}<p class="muted small">Server snapshots do not protect against losing the server disk. Keep an exported copy on another device or back up snapshots to another disk.</p><button class="btn secondary full" id="export-protection">Export journal JSON</button><p id="protection-error" class="notice" hidden></p>`);
    document.querySelector('#export-protection').onclick=exportData;
    document.querySelector('#create-recovery').onclick=async e=>{
      e.target.disabled=true;
      try{
        await backend.flush();
        const result=await backend.request('recovery/code',{method:'POST'});
        openSheet('Save your recovery code.','Shown once. Keep it in your password manager or download it.',`<div class="notice green"><code style="display:block;overflow-wrap:anywhere;font-size:16px;user-select:all">${esc(result.code)}</code></div><p class="muted small">Use Settings → Recover journal on another browser, LAN address, or VPN address to open this same journal. A replacement code invalidates this one. Existing connected devices stay connected.</p><button class="btn full" id="download-recovery">Download recovery code</button>`);
        document.querySelector('#download-recovery').onclick=()=>downloadText(`BurnRate recovery code\n\n${result.code}\n\nKeep this private. Anyone with this code can access your journal.\nUse Settings > Recover journal on your BurnRate server.\n`, `burnrate-recovery-${today}.txt`, 'text/plain');
      }catch(error){const message=document.querySelector('#protection-error');message.textContent=error.message;message.hidden=false;e.target.disabled=false;}
    };
  }catch(error){openSheet('Recovery & backups.','Export a copy to protect browser-only data.',`<div class="notice">${esc(error.message)}</div><button class="btn full" id="export-protection">Export journal JSON</button>`);document.querySelector('#export-protection').onclick=exportData;}
}
function recoverJournalSheet(){
  openSheet('Recover your journal.','Upload your saved recovery file or enter your code.',`<form id="recover-form"><label class="field">Upload recovery code<input id="recovery-file" type="file" accept=".txt,text/plain"></label><p class="muted small">Choose the .txt file downloaded from BurnRate. The file is read on this device.</p><p id="recovery-file-status" class="notice green" role="status" hidden></p><label class="field">Or enter recovery code<input name="code" required maxlength="100" autocomplete="off" autocapitalize="characters" spellcheck="false" placeholder="BR-…"></label><p class="muted small">This switches the journal in this browser. Your current journal will be exported first; the server keeps it separately. Both devices must reach the same BurnRate server.</p><p id="recover-error" class="notice" role="alert" hidden></p><button class="btn full" type="submit">Recover journal</button></form>`);
  const form=document.querySelector('#recover-form'),picker=document.querySelector('#recovery-file');
  let selection=0;
  picker.onchange=async()=>{
    const attempt=++selection,file=picker.files[0],input=form.elements.code;
    const error=form.querySelector('#recover-error'),status=form.querySelector('#recovery-file-status'),submit=form.querySelector('button');
    error.hidden=true;status.hidden=true;
    if(!file){submit.disabled=false;return;}
    input.value='';submit.disabled=true;
    try{
      if(file.size>16384)throw new Error('Choose a recovery text file smaller than 16 KB.');
      const code=parseRecoveryFile(await file.text());
      if(attempt!==selection||!form.isConnected)return;
      input.value=code;status.textContent='Recovery file ready. Choose Recover journal to continue.';status.hidden=false;
    }catch(problem){if(attempt===selection&&form.isConnected){error.textContent=problem.message;error.hidden=false;}}
    finally{if(attempt===selection&&form.isConnected)submit.disabled=false;}
  };
  document.querySelector('#recover-form').onsubmit=async e=>{
    e.preventDefault();const submit=e.target.querySelector('button'),code=new FormData(e.target).get('code');submit.disabled=true;picker.disabled=true;form.elements.code.disabled=true;
    try{
      if(!window.BURNRATE_API)throw new Error('Open your Python server address to recover a server journal.');
      if(backend.connected&&!backend.blocked)await backend.flush();
      if(backend.running)await backend.running.catch(()=>{});
      exportData();
      const result=await backend.request('recovery/restore',{method:'POST',body:JSON.stringify({code})});
      if(!result.state)throw new Error('Recovered journal has no saved data.');
      backend.pending=null;backend.blocked=false;backend.connected=true;backend.revision=result.revision;backend.capabilities=result.capabilities;
      state=result.state;state.plan=null;activePhotoDraft=null;draft=[];editMeal=null;useAI=false;latestReview=null;dailyRecap=null;recapLoaded=false;recapGeneration++;
      hydrating=true;persist();hydrating=false;selected=today;sheet.close();render();toast('Recovered your server journal');await refreshDailyRecap();
      await refreshServerPlan(false);
    }catch(error){const message=document.querySelector('#recover-error');message.textContent=error.message;message.hidden=false;submit.disabled=false;picker.disabled=false;form.elements.code.disabled=false;}
  };
}
function downloadText(content,filename,type){const url=URL.createObjectURL(new Blob([content],{type})),a=document.createElement('a');a.href=url;a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function exportData(){downloadText(JSON.stringify(state,null,2),`burnrate-${today}.json`,'application/json');toast('Journal exported')}
function importData(){const input=document.createElement('input');input.type='file';input.accept='.json,application/json';input.onchange=async()=>{const file=input.files[0];if(!file)return;try{if(file.size>5e6)throw Error();const data=JSON.parse(await file.text());if(!validBackup(data))throw Error();confirmSheet('Restore this journal?','This replaces your current browser journal with the selected backup.',()=>{state=data;state.plan=null;persist();selected=today;render();toast('Journal restored')})}catch{toast('This file is not a valid BurnRate backup')}};input.click()}
function validBackup(s){const finite=n=>typeof n==='number'&&Number.isFinite(n);const date=d=>/^\d{4}-\d{2}-\d{2}$/.test(d||'')&&!Number.isNaN(new Date(d).getTime());return s?.version===1&&typeof s.demo==='boolean'&&finite(s.revision)&&typeof s.settings?.name==='string'&&s.settings.name.length<=40&&[s.settings.startWeight,s.settings.targetWeight,s.settings.calorieFloor,s.settings.proteinTarget,s.settings.waterTarget,s.settings.availableMinutes].every(n=>finite(n)&&n>=0)&&s.settings.calorieFloor>0&&s.settings.proteinTarget>0&&s.settings.waterTarget>0&&date(s.settings.endDate)&&['Lunch','Snack','Dinner'].every(k=>/^\d{2}:\d{2}$/.test(s.settings.mealTimes?.[k]||''))&&typeof s.settings.eatFrom==='string'&&typeof s.settings.eatUntil==='string'&&Array.isArray(s.meals)&&s.meals.every(m=>typeof m.id==='string'&&date(m.date)&&typeof m.slot==='string'&&Array.isArray(m.items)&&m.items.every(i=>typeof i.name==='string'&&typeof i.unit==='string'&&[i.amount,i.kcal,i.low,i.high].every(n=>finite(n)&&n>=0)&&i.amount>0&&i.low<=i.high&&(i.protein===null||finite(i.protein))))&&Array.isArray(s.activities)&&s.activities.every(a=>typeof a.id==='string'&&typeof a.name==='string'&&['most','mid','least'].includes(a.preference)&&typeof a.enabled==='boolean')&&Array.isArray(s.sessions)&&s.sessions.every(a=>date(a.date)&&typeof a.name==='string'&&typeof a.activityId==='string'&&finite(a.duration)&&finite(a.effort)&&(a.steps==null||(Number.isInteger(a.steps)&&a.steps>=0&&a.steps<=200000)))&&Array.isArray(s.weights)&&s.weights.every(w=>date(w.date)&&finite(w.kg)&&w.kg>0)&&s.days&&Object.values(s.days).every(d=>finite(d.water)&&(d.sleep===null||finite(d.sleep))&&(d.energy===null||finite(d.energy)))&&Array.isArray(s.savedPresets)&&s.savedPresets.every(p=>typeof p.id==='string'&&typeof p.name==='string'&&Array.isArray(p.items)&&p.items.every(i=>(i.food&&catalog.some(c=>c.id===i.food)&&finite(i.amount)&&i.amount>0)||(!i.food&&typeof i.name==='string'&&finite(i.kcal)&&finite(i.amount)&&i.amount>0)));}
persist();render();
if(window.BURNRATE_API){hydrating=true;backend.initialize(state).then(async loaded=>{if(loaded){state=loaded;persist();render();toast('Python backend connected');}}).catch(error=>{backend.connected=false;toast('Browser mode available. '+error.message)}).finally(async()=>{hydrating=false;if(backend.connected){await refreshServerPlan(false);await refreshDailyRecap()}});}
